insert into lhq_labels (key, locale, value) values
('PRIVACY_LAST_UPDATED','ar','آخر تحديث: نوفمبر 2026'),
('PRIVACY_SECTION_THIRD_PARTY_BODY','ar','تتكامل LiquidityHQ مع خدمات طرف ثالث تشمل Supabase (قاعدة البيانات)، وPostHog (تحليلات المنتج وتسجيل الجلسات)، وxAI Grok (تحليل بالذكاء الاصطناعي)، وBrevo (إرسال البريد الإلكتروني)، وWhop (المدفوعات)، وGlitchTip (تقارير الأخطاء)، وCloudflare Turnstile (التحقق من الروبوتات في نماذج تسجيل الدخول وإنشاء الحساب وإعادة تعيين كلمة المرور). يتولى Telegram توصيل التنبيهات التي تربطها. تأتي بيانات السوق والأخبار من: Binance وBybit وOKX وHyperliquid (الأسعار ومعدلات التمويل والفائدة المفتوحة ونسب المراكز الطويلة إلى القصيرة والتصفيات)؛ وCoinbase (علاوة BTC)؛ وDeribit (خيارات BTC)؛ وCoinMarketCap (هيمنة BTC)؛ وCoinGecko (أعلى المستويات التاريخية)؛ وSoSoValue (تدفقات صناديق ETF الفورية)؛ وDefiLlama (معروض العملات المستقرة)؛ وblockchain.info (بيانات شبكة البيتكوين)؛ وAlternative.me (مؤشر الخوف والجشع)؛ وYahoo Finance (مؤشرات الأسهم والذهب والنفط ومؤشر الدولار)؛ وExchangeRate-API (أسعار العملات)؛ وBLS وBEA وCensus والاحتياطي الفيدرالي (جداول إصدار البيانات الاقتصادية)؛ وFRED (البيانات الاقتصادية لبنك الاحتياطي الفيدرالي في سانت لويس)؛ وFinnhub وخلاصات RSS من الناشرين الإخباريين (الأخبار). لهذه الجهات سياسات خصوصية وممارسات بيانات خاصة بها، ولسنا مسؤولين عن كيفية تعاملها مع البيانات.'),
('PRIVACY_LAST_UPDATED','en','Last updated: November 2026'),
('PRIVACY_SECTION_THIRD_PARTY_BODY','en','LiquidityHQ integrates with third-party services including Supabase (database), PostHog (product analytics and session recording), xAI Grok (AI analysis), Brevo (email delivery), Whop (payments), GlitchTip (error reports) and Cloudflare Turnstile (the bot check on the sign-in, sign-up and password reset forms). Telegram delivers the alerts you connect. Market and news data come from: Binance, Bybit, OKX and Hyperliquid (prices, funding rates, open interest, long/short ratios and liquidations); Coinbase (BTC premium); Deribit (BTC options); CoinMarketCap (BTC dominance); CoinGecko (all-time highs); SoSoValue (spot ETF flows); DefiLlama (stablecoin supply); blockchain.info (Bitcoin network data); Alternative.me (Fear & Greed index); Yahoo Finance (stock indices, gold, oil and the dollar index); ExchangeRate-API (currency rates); BLS, BEA, Census and the Federal Reserve (economic release schedules); FRED, St. Louis Federal Reserve (economic data); Finnhub and RSS feeds from news publishers (news). These providers have their own privacy policies and data practices. We are not responsible for their data handling.'),
('PRIVACY_LAST_UPDATED','ko','최종 업데이트: 2026년 11월'),
('PRIVACY_SECTION_THIRD_PARTY_BODY','ko','LiquidityHQ는 Supabase(데이터베이스), PostHog(제품 분석 및 세션 기록), xAI Grok(AI 분석), Brevo(이메일 발송), Whop(결제), GlitchTip(오류 보고), Cloudflare Turnstile(로그인, 가입, 비밀번호 재설정 양식의 봇 확인) 등 제3자 서비스와 연동됩니다. 텔레그램은 연결한 알림을 전달합니다. 시장 및 뉴스 데이터 출처: 바이낸스, 바이빗, OKX, Hyperliquid(가격, 펀딩비, 미결제약정, 롱/숏 비율, 청산), 코인베이스(BTC 프리미엄), Deribit(BTC 옵션), CoinMarketCap(BTC 도미넌스), CoinGecko(사상 최고가), SoSoValue(현물 ETF 자금 흐름), DefiLlama(스테이블코인 공급량), blockchain.info(비트코인 네트워크 데이터), Alternative.me(공포·탐욕 지수), Yahoo Finance(주가지수, 금, 원유, 달러 인덱스), ExchangeRate-API(환율), BLS, BEA, Census, 연방준비제도(경제지표 발표 일정), FRED(세인트루이스 연방준비은행 경제 데이터), Finnhub 및 언론사 RSS 피드(뉴스). 이러한 제공업체는 자체 개인정보 처리방침과 데이터 관행을 따르며, 당사는 이들의 데이터 처리에 대해 책임지지 않습니다.'),
('PRIVACY_LAST_UPDATED','ru','Последнее обновление: ноябрь 2026 г.'),
('PRIVACY_SECTION_THIRD_PARTY_BODY','ru','LiquidityHQ использует сторонние сервисы, включая Supabase (база данных), PostHog (аналитика продукта и запись сессий), xAI Grok (AI-анализ), Brevo (доставка почты), Whop (платежи), GlitchTip (отчёты об ошибках) и Cloudflare Turnstile (проверка на ботов в формах входа, регистрации и сброса пароля). Telegram доставляет оповещения, которые вы подключили. Рыночные данные и новости поступают от: Binance, Bybit, OKX и Hyperliquid (цены, ставки фандинга, открытый интерес, соотношение лонгов и шортов, ликвидации); Coinbase (премия BTC); Deribit (опционы BTC); CoinMarketCap (доминирование BTC); CoinGecko (исторические максимумы); SoSoValue (потоки спотовых ETF); DefiLlama (предложение стейблкоинов); blockchain.info (данные сети Биткоина); Alternative.me (индекс страха и жадности); Yahoo Finance (фондовые индексы, золото, нефть и индекс доллара); ExchangeRate-API (курсы валют); BLS, BEA, Census и ФРС (графики публикации экономических данных); FRED (экономические данные ФРБ Сент-Луиса); Finnhub и RSS-ленты новостных изданий (новости). Эти поставщики имеют собственные политики конфиденциальности и практики обработки данных - мы не несём ответственности за то, как они обрабатывают данные.'),
('PRIVACY_LAST_UPDATED','zh','最后更新：2026年11月'),
('PRIVACY_SECTION_THIRD_PARTY_BODY','zh','LiquidityHQ 集成了以下第三方服务：Supabase（数据库）、PostHog（产品分析与会话录制）、xAI Grok（AI 分析）、Brevo（邮件发送）、Whop（支付）、GlitchTip（错误报告）和 Cloudflare Turnstile（登录、注册和重置密码表单的机器人验证）。Telegram 负责发送你已连接的提醒。市场与新闻数据来源：币安、Bybit、OKX 和 Hyperliquid（价格、资金费率、未平仓合约、多空比与爆仓）；Coinbase（BTC 溢价）；Deribit（BTC 期权）；CoinMarketCap（BTC 市值占比）；CoinGecko（历史最高价）；SoSoValue（现货 ETF 资金流）；DefiLlama（稳定币供应量）；blockchain.info（比特币网络数据）；Alternative.me（恐惧与贪婪指数）；Yahoo Finance（股指、黄金、原油与美元指数）；ExchangeRate-API（汇率）；BLS、BEA、Census 与美联储（经济数据发布日程）；FRED（圣路易斯联邦储备银行经济数据）；Finnhub 及新闻媒体的 RSS 订阅（新闻）。这些服务提供商各自拥有独立的隐私政策与数据处理方式，我们不对其数据处理行为负责。')
